import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-text-field.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** The live region of `politeness` in the shadow root of `el`. */
function annRegion(el: HTMLElement, politeness: 'polite' | 'assertive') {
  return el.shadowRoot!.querySelector<HTMLElement>(`[data-announcer="${politeness}"]`);
}

/** Waits (at most a second) until the live region holds `expected`, and returns its text. */
async function annText(el: HTMLElement, politeness: 'polite' | 'assertive', expected: string) {
  const text = () => annRegion(el, politeness)?.textContent?.trim() ?? '';
  // Checks once per frame (the shared until() helper, inlined).
  const end = performance.now() + 1000;
  while (text() !== expected && performance.now() < end) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
  }
  return text();
}

describe('<md-gb-text-field> announcer contract (AnnouncerController)', () => {
  afterEach(() => container?.remove());

  it('gives its error message the alert role', async () => {
    // spec: text-fields-fe438b, text-fields-7bc15d
    const root = await mount(html`
      <button id="before">Before</button>
      <md-gb-text-field label="ZIP code" error error-text="Not a valid ZIP code"></md-gb-text-field>
    `);
    const el = root.querySelector<any>('md-gb-text-field')!;
    const before = root.querySelector<HTMLElement>('#before')!;
    before.focus();
    await settle();
    const message = el.shadowRoot.querySelector('#supporting-text') as HTMLElement;
    expect(message.textContent).toBe('Not a valid ZIP code');
    expect(message.getAttribute('role')).toBe('alert');
  });

  it('announces an unchanged error message again, assertively, when it is reported again', async () => {
    // spec: text-fields-fe438b, text-fields-7bc15d
    const root = await mount(html`
      <button id="before">Before</button>
      <md-gb-text-field label="Email" required></md-gb-text-field>
    `);
    const el = root.querySelector<any>('md-gb-text-field')!;
    const before = root.querySelector<HTMLElement>('#before')!;
    before.focus();
    await settle();
    el.reportValidity();
    await settle();
    el.reportValidity();
    const expected = el.validationMessage;
    expect(expected).not.toBe('');
    expect(await annText(el, 'assertive', expected)).toBe(expected);
    const region = annRegion(el, 'assertive')!;
    expect(region.getAttribute('role')).toBe('alert');
    expect(region.getAttribute('aria-live')).toBe('assertive');
    expect(region.getAttribute('aria-atomic')).toBe('true');
  });

  it('removes its live regions when it disconnects', async () => {
    const root = await mount(html`<md-gb-text-field label="Email" required></md-gb-text-field>`);
    const el = root.querySelector<any>('md-gb-text-field')!;
    el.reportValidity();
    await settle();
    el.reportValidity();
    await annText(el, 'assertive', el.validationMessage);
    expect(el.shadowRoot.querySelector('[data-announcer]')).not.toBeNull();
    el.remove();
    await settle();
    expect(el.shadowRoot.querySelector('[data-announcer]')).toBeNull();
  });
});

/** The form's entries, as submitted. */
function submittedEntries(form: HTMLFormElement) {
  return [...new FormData(form).entries()].map(([k, v]) => [k, String(v)]);
}

async function setupFormText(attrs: Record<string, string> = {}) {
  const root = await mount(html`
    <form>
      <fieldset>
        <md-gb-text-field name="q" label="Name" supporting-text="Enter your name"></md-gb-text-field>
      </fieldset>
    </form>
  `);
  const el = root.querySelector<any>('md-gb-text-field')!;
  for (const [name, value] of Object.entries(attrs)) el.setAttribute(name, value);
  await settle();
  return {
    el,
    form: root.querySelector('form')!,
    fieldset: root.querySelector('fieldset')!,
    input: () => (el.shadowRoot as ShadowRoot).querySelector<HTMLInputElement>('input')!,
    label: () => el.shadowRoot!.querySelector('.text-field-label')!.textContent!.trim(),
    /** The supporting or error text shown, one entry per element. */
    supporting: () =>
      [...el.shadowRoot!.querySelectorAll('.text-field-supporting-text')].map((e) => e.textContent!.trim()),
  };
}

/** Replaces the text by typing on a real keyboard. */
async function typeFormText(el: any, text: string) {
  el.focus();
  el.select();
  await sendKeys({type: text});
  await settle();
}

describe('<md-gb-text-field> form contract (shared form layer)', () => {
  afterEach(() => container?.remove());

  it('submits the typed text under its name', async () => {
    const f = await setupFormText();
    await typeFormText(f.el, 'Ada');
    expect(f.el.value).toBe('Ada');
    expect(submittedEntries(f.form)).toEqual([['q', 'Ada']]);
  });

  it('shows the value attribute as the default and ignores it once edited, until reset', async () => {
    const f = await setupFormText({value: 'Ada'});
    expect(f.el.value).toBe('Ada');
    expect(f.el.defaultValue).toBe('Ada');
    expect(submittedEntries(f.form)).toEqual([['q', 'Ada']]);
    await typeFormText(f.el, 'Bob');
    expect(submittedEntries(f.form)).toEqual([['q', 'Bob']]);
    f.el.setAttribute('value', 'Eve');
    await settle();
    expect(f.el.value).toBe('Bob');
    f.form.reset();
    await settle();
    expect(f.el.value).toBe('Eve');
    expect(submittedEntries(f.form)).toEqual([['q', 'Eve']]);
    f.el.setAttribute('value', 'Zed');
    await settle();
    expect(f.el.value).toBe('Zed');
  });

  it('resets to an empty value without a value attribute', async () => {
    const f = await setupFormText();
    await typeFormText(f.el, 'Ada');
    f.form.reset();
    await settle();
    expect(f.el.value).toBe('');
    expect(f.input().value).toBe('');
  });

  it('restores the saved value', async () => {
    const f = await setupFormText();
    f.el.formStateRestoreCallback('saved', 'restore');
    await settle();
    expect(f.el.value).toBe('saved');
    expect(f.input().value).toBe('saved');
    expect(submittedEntries(f.form)).toEqual([['q', 'saved']]);
  });

  it('is invalid while required and empty, valid once typed, and marks the label', async () => {
    // spec: text-fields-bb9bb0, text-fields-c95e3a
    const f = await setupFormText({required: ''});
    expect(f.label()).toBe('Name*');
    expect(f.el.validity.valueMissing).toBeTrue();
    expect(f.el.checkValidity()).toBeFalse();
    expect(f.form.checkValidity()).toBeFalse();
    await typeFormText(f.el, 'Ada');
    expect(f.el.validity.valid).toBeTrue();
    expect(f.form.checkValidity()).toBeTrue();
  });

  it('setCustomValidity() invalidates until cleared', async () => {
    // spec: text-fields-bb9bb0, text-fields-c95e3a
    const f = await setupFormText();
    f.el.setCustomValidity('Taken');
    expect(f.el.validity.customError).toBeTrue();
    expect(f.el.validationMessage).toBe('Taken');
    expect(f.form.checkValidity()).toBeFalse();
    f.el.setCustomValidity('');
    expect(f.el.validity.valid).toBeTrue();
  });

  it('blocks a submit while invalid and lets it through once valid', async () => {
    // spec: text-fields-bb9bb0, text-fields-c95e3a
    const f = await setupFormText({required: ''});
    let submitted = 0;
    f.form.addEventListener('submit', (e) => {
      e.preventDefault();
      submitted++;
    });
    f.form.requestSubmit();
    expect(submitted).toBe(0);
    await typeFormText(f.el, 'Ada');
    f.form.requestSubmit();
    expect(submitted).toBe(1);
  });

  it('reportValidity() replaces the supporting text with the error text until valid', async () => {
    // spec: text-fields-a273a8, text-fields-ff83d3, text-fields-f07a24, text-fields-f329f6
    const f = await setupFormText({required: ''});
    let invalid = 0;
    f.el.addEventListener('invalid', () => invalid++);
    expect(f.supporting()).toEqual(['Enter your name']);
    expect(f.el.reportValidity()).toBeFalse();
    await settle();
    expect(invalid).toBe(1);
    const message = f.el.validationMessage;
    expect(message).not.toBe('');
    // One line of text: the error replaces the supporting text, not adds to it.
    expect(f.supporting()).toEqual([message]);
    expect(f.el.shadowRoot!.querySelector('[role="alert"]')!.textContent!.trim()).toBe(message);
    expect(f.input().getAttribute('aria-invalid')).toBe('true');
    await typeFormText(f.el, 'Ada');
    expect(f.supporting()).toEqual(['Enter your name']);
    expect(f.el.shadowRoot!.querySelector('[role="alert"]')).toBeNull();
    expect(f.input().getAttribute('aria-invalid')).toBe('false');
  });

  it('shows the error when a submit is blocked', async () => {
    // spec: text-fields-a273a8, text-fields-ff83d3, text-fields-f07a24, text-fields-f329f6
    const f = await setupFormText({required: ''});
    f.form.requestSubmit();
    await settle();
    expect(f.supporting()).toEqual([f.el.validationMessage]);
    expect(f.input().getAttribute('aria-invalid')).toBe('true');
  });

  it('shows and follows a custom validity message', async () => {
    // spec: text-fields-a273a8, text-fields-ff83d3, text-fields-f07a24, text-fields-f329f6
    const f = await setupFormText();
    f.el.setCustomValidity('Taken');
    expect(f.el.reportValidity()).toBeFalse();
    await settle();
    expect(f.supporting()).toEqual(['Taken']);
    f.el.setCustomValidity('Reserved');
    await settle();
    expect(f.supporting()).toEqual(['Reserved']);
    f.el.setCustomValidity('');
    await settle();
    expect(f.supporting()).toEqual(['Enter your name']);
  });

  it('prefers the error and error text the page sets', async () => {
    // spec: text-fields-a273a8, text-fields-ff83d3, text-fields-f07a24, text-fields-f329f6
    const f = await setupFormText({required: '', error: '', 'error-text': 'Use your real name'});
    expect(f.supporting()).toEqual(['Use your real name']);
    expect(f.el.reportValidity()).toBeFalse();
    await settle();
    expect(f.supporting()).toEqual(['Use your real name']);
  });

  it('clears the error on form reset', async () => {
    // spec: text-fields-a273a8, text-fields-ff83d3, text-fields-f07a24, text-fields-f329f6
    const f = await setupFormText({required: ''});
    f.el.reportValidity();
    await settle();
    expect(f.input().getAttribute('aria-invalid')).toBe('true');
    f.form.reset();
    await settle();
    expect(f.supporting()).toEqual(['Enter your name']);
    expect(f.input().getAttribute('aria-invalid')).toBe('false');
  });

  it('counts the characters against the limit', async () => {
    // spec: text-fields-647ded, text-fields-cf0f7a
    const f = await setupFormText({maxlength: '10'});
    const counter = () => f.el.shadowRoot!.querySelector('.text-field-counter')!.textContent!.trim();
    expect(counter()).toBe('0/10');
    await typeFormText(f.el, 'Ada');
    expect(counter()).toBe('3/10');
  });

  it('follows a disabled fieldset, is left out of the form and recovers', async () => {
    // spec: text-fields-70a237, text-fields-08ec44, text-fields-7c17c3, text-fields-d37c73
    const f = await setupFormText({value: 'Ada', required: ''});
    expect(f.el.disabled).toBeFalse();
    f.fieldset.disabled = true;
    await settle();
    expect(f.el.disabled).toBeTrue();
    expect(f.input().disabled).toBeTrue();
    expect(submittedEntries(f.form)).toEqual([]);
    expect(f.el.willValidate).toBeFalse();
    f.fieldset.disabled = false;
    await settle();
    expect(f.el.disabled).toBeFalse();
    expect(f.input().disabled).toBeFalse();
    expect(submittedEntries(f.form)).toEqual([['q', 'Ada']]);
    expect(f.el.willValidate).toBeTrue();
  });
});
